Selector sel = Selector.open();
ServerSocketChannel ssc = ServerSocketChannel.open();
ssc.bind(new InetSocketAddress(8080)).configureBlocking(false);
ssc.register(sel, SelectionKey.OP_ACCEPT);

while (running) {
    sel.select();                       // one pool thread is the leader
    for (SelectionKey k : sel.selectedKeys()) {
        if (k.isAcceptable()) accept(ssc);
        else read((SocketChannel) k.channel());
    }
    sel.selectedKeys().clear();         // consume, or the key stays ready
}
